svg.appendChild(el("text",{x:margin.left+PW+4,y:margin.top+4,"text-anchor":"start","font-size":"7.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#888"},"Hike odds"));
