  svg.appendChild(el("text",{x:margin.left-6,y:yr(ry)+3,"text-anchor":"end","font-size":"8.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#aaaaaa"}, ry+"%"));
}
