svg.appendChild(el("path",{d:corePath,fill:"none",stroke:"#6b7280","stroke-width":"1.5","stroke-dasharray":"4,2"}));
for (var i=0;i<n;i++){
  svg.appendChild(el("text",{x:xp(i),y:H-margin.bottom+16,"text-anchor":"middle","font-size":"7.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#999999"}, data[i].m));
}
var lastX = xp(n-1), lastY = yv(data[n-1].h);
svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
var pillW = 46, pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH/2;
svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,fill:"#e8a825",rx:"3"}));
svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#111111"},"3.2%"));
var lastCY = yv(data[n-1].c);
svg.appendChild(el("circle",{cx:lastX,cy:lastCY,r:3,fill:"#6b7280"}));
svg.appendChild(el("text",{x:lastX-4,y:lastCY+14,"text-anchor":"end","font-size":"7.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#888888"},"Core trim 2.0%"));
