}
var data = [{d:"Feb 28",v:0.5},{d:"Mar 7",v:0.3},{d:"Mar 14",v:0.4},{d:"Mar 21",v:0.6},{d:"Mar 28",v:0.5},{d:"Apr 4",v:0.4},{d:"Apr 11",v:0.7},{d:"Apr 18",v:0.6},{d:"Apr 25",v:0.8},{d:"May 2",v:0.9},{d:"May 9",v:1.1},{d:"May 16",v:1.0},{d:"May 23",v:1.3},{d:"May 30",v:1.5},{d:"Jun 6",v:1.8},{d:"Jun 13",v:2.4},{d:"Jun 18",v:3.6},{d:"Jun 24",v:4.8}];
var n = data.length;
var margin = {left:62,right:24,top:18,bottom:46};
var W = 680, H = 300;
var PW = W - margin.left - margin.right;
var PH = H - margin.top - margin.bottom;
var yMin = 0, yMax = 16;
function xp(i){ return margin.left + (i/(n-1)) * PW; }
function yv(v){ return margin.top + PH - ((v-yMin)/(yMax-yMin)) * PH; }
var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");
for (var gy=0; gy<=16; gy+=4){
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:yv(gy),y2:yv(gy),stroke:"#ececec","stroke-width":"0.5"}));
  svg.appendChild(el("text",{x:margin.left-6,y:yv(gy)+3,"text-anchor":"end","font-size":"8.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#aaaaaa"}, gy+"M"));
}
svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:yv(15),y2:yv(15),stroke:"#7a3030","stroke-width":"1","stroke-dasharray":"3,3"}));
svg.appendChild(el("text",{x:margin.left+10,y:yv(15)-5,"text-anchor":"start","font-size":"7","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#7a3030"},"PREWAR LEVEL: 15M BPD"));
var areaPath = "M" + xp(0) + "," + yv(0) + " ";
data.forEach(function(pt,i){ areaPath += "L" + xp(i) + "," + yv(pt.v) + " "; });
areaPath += "L" + xp(n-1) + "," + yv(0) + " Z";
svg.appendChild(el("path",{d:areaPath,fill:"#4a5568","fill-opacity":"0.12",stroke:"none"}));
var linePath = "";
data.forEach(function(pt,i){ linePath += (i===0?"M":"L") + xp(i) + "," + yv(pt.v) + " "; });
svg.appendChild(el("path",{d:linePath,fill:"none",stroke:"#4a5568","stroke-width":"2"}));
for (var i=0;i<n;i+=3){
  svg.appendChild(el("text",{x:xp(i),y:H-margin.bottom+16,"text-anchor":"middle","font-size":"7.5","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#999999"}, data[i].d));
}
var lastX = xp(n-1), lastY = yv(data[n-1].v);
svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
var pillW = 60, pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH/2;
if (pillX < margin.left) pillX = lastX + 6;
svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,fill:"#e8a825",rx:"3"}));
svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#111111"},"4.8M bpd"));
if(_cs && _cs.parentNode) _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: Kpler shipping data via CNBC, June 24, 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Flow figures are approximate weekly composites derived from reported daily transit volumes. The prewar reference line of 15 million barrels per day reflects average flow before February 28, 2026.</p>
<h2>The Realistic Portfolio Implication</h2>
<p>This is not a call to position for a renewed energy shock. The base case, continued gradual reopening with periodic friction, remains more likely than a full re-closure, and Canadian energy and TSX exposure has already adjusted substantially to a lower, calmer oil price over the past month.</p>
<p>It is a case for treating August 17 as a real date on the calendar rather than background noise. A client whose portfolio review or rebalancing falls in the weeks immediately before that date should have the toll-mechanism sanctions collision specifically on the agenda, not because it is the likely outcome, but because it is the one outcome the market has done the least work pricing.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">What They''re Feeling</div>
<p>Clients with energy exposure feel relief that the Hormuz crisis appears to be resolving and may be inclined to treat the story as closed. That relief is not unreasonable given the data, but it can shade into complacency about a deal whose central guarantee has a hard expiry date in eight weeks.</p>
<p>Clients without direct energy exposure who have been following the story passively likely have not registered the August 17 toll-free deadline at all, since most coverage has focused on tanker traffic and ceasefire status rather than the underlying legal mechanism.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">What to Say</div>
<div class="script-box">The Hormuz situation has genuinely improved, oil is back under $70 and tanker traffic is recovering, and that is reflected in how calm energy markets have been. What is worth knowing is that the deal guaranteeing free passage through the strait expires around August 17. After that, Iran has said it intends to start charging tolls, and the body it has designated to collect those tolls is already under US sanctions, which makes paying it illegal for most Western shipping companies. That does not mean a crisis is coming. The most likely outcome is some kind of extension or workaround gets negotiated before the deadline, the way several smaller flashpoints in this conflict have been handled so far. But I want you to know the date is real, and I am watching it, rather than treating the story as fully resolved just because oil has come down.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Who''s Affected</div>
<p><strong>High impact:</strong> Clients with concentrated exposure to Canadian energy producers or energy-adjacent sectors who benefited from the war premium and may now be assuming a permanently calmer oil price without accounting for the August deadline.</p>
<p><strong>Mixed impact:</strong> Clients with broadly diversified portfolios where energy is a modest sector weight. The August 17 date is worth flagging but does not warrant portfolio changes on its own.</p>
<p><strong>Potential benefit:</strong> Clients holding gold or other safe-haven positions established during the conflict who may want to understand that a renewed Hormuz disruption, however unlikely, is one of the few remaining catalysts that could revive safe-haven demand against the current Fed-driven headwind.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Action Checklist</div>
<div class="checklist-item">Mark August 17 on the calendar as a date to revisit Hormuz-related positioning, distinct from any other scheduled portfolio review.</div>
<div class="checklist-item">Review energy sector weightings for clients who added exposure during the conflict''s peak, to confirm sizing still reflects current risk rather than April''s risk level.</div>
<div class="checklist-item">Flag any client communication referencing the Hormuz crisis as resolved, and correct framing toward ongoing but currently moderate risk.</div>
<div class="checklist-item">Note that Canada has joined the multinational mine-clearance mission, which is a useful, low-alarm talking point for clients asking how the situation might evolve.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Follow-Up Email Template</div>
<div class="email-box" id="respond-email">
<strong>Subject:</strong> The Hormuz deadline most coverage is missing<br><br>
Hi [Client Name],<br><br>
Following up on our conversation about the Strait of Hormuz situation. The headline news is genuinely positive: oil has fallen below $70 a barrel and tanker traffic through the strait continues to recover.<br><br>
One detail worth knowing: the agreement guaranteeing toll-free passage through the strait expires around August 17. Iran has indicated it intends to start charging fees after that date, through a body that is already under US sanctions, which creates a legal complication for the shipping companies that would need to pay it.<br><br>
This is not a prediction of renewed crisis. The more likely outcome is some form of extension or workaround before the deadline. I simply wanted you to have the date on your radar rather than treating the Hormuz story as fully closed.<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copy email</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Client Profiles to Target</div>
<p><strong>DIY investors who added energy exposure during the conflict and have not revisited it:</strong> They are likely tracking the headline oil price but unlikely to know about the August 17 toll deadline, a detail that has received far less coverage than tanker traffic or ceasefire status.</p>
<p><strong>Clients of advisors who have framed the Hormuz story as fully resolved:</strong> An advisor who has not flagged the toll mechanism''s sanctions complication has left a real gap in the client''s understanding of the remaining risk.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Opening Line</div>
<div class="script-box">Most of what you have heard about the Strait of Hormuz situation is genuinely good news, but there is a deadline in mid-August that most coverage has not connected to a real legal complication. Do you have a few minutes to walk through it?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Value Proposition</div>
<p>A self-directed investor following the Hormuz story through headlines sees tanker counts and oil prices, the surface-level indicators, but rarely encounters the underlying legal mechanism: that the entity designated to collect Hormuz tolls after the current free-passage window is itself under US sanctions, making the planned toll-collection regime a structural collision waiting to happen.</p>
<p>The advisor''s value is tracking that kind of mechanism-level detail continuously, not just the headline price, and translating it into a specific, calibrated portfolio implication rather than either dismissing the risk or overreacting to it.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Discovery Questions</div>
<p>Do you currently hold any direct or sector exposure to Canadian energy that was added specifically because of the Hormuz crisis?</p>
<p>Were you aware that the toll-free passage guarantee for the strait has a specific expiry date in mid-August?</p>
<p>How do you currently decide when a geopolitical story that seems resolved actually still carries portfolio-relevant risk?</p>
<p>If oil prices moved sharply in either direction over the next two months, would you know which catalysts to watch for first?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Prospecting Email Template</div>
<div class="email-box" id="prospect-email">
<strong>Subject:</strong> The Hormuz story is not as resolved as it looks<br><br>
Hi [Name],<br><br>
Oil has fallen below $70 a barrel and the Strait of Hormuz crisis looks largely resolved from the headlines. But the agreement behind that calm has a real expiry date around August 17, after which Iran intends to charge tolls through a mechanism that is already under US sanctions.<br><br>
That detail has gotten far less attention than the tanker traffic numbers, and it is exactly the kind of thing that matters for energy and broader portfolio positioning over the next two months.<br><br>
If you would like to talk through how this affects your current positioning, I would be glad to set up a short call.<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
